begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) select ('a0000000-0000-4000-8000-00000000000'||i)::uuid,'invite'||i||'@example.test',now() from generate_series(1,4) i;
create temporary table invite_state(key text primary key, value text);
grant all on invite_state to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
insert into invite_state values('child',public.create_child('{"name":"TEST","dob":"2025-10-01"}','{"memories":true,"milestones":true,"health":true,"personalisation":true,"notifications":true}',true,'2026-10-24.v2')::text);
insert into invite_state select 'invite',public.create_invite((select value::uuid from invite_state where key='child'),'invite2@example.test','family_viewer','Grandparent')::text;
select is((select count(*) from public.child_invites),0::bigint,'Invite hashes never exposed');
select is((select count(*) from public.list_invites((select value::uuid from invite_state where key='child'))),1::bigint,'Owner sees safe invitation summary');
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000003',true);
select throws_ok($$select public.accept_invite((select value::jsonb->>'token' from invite_state where key='invite'),' {"memories":true,"milestones":false,"health":false,"personalisation":false,"notifications":false}',true,'2026-10-24.v2')$$,'PT403','This invitation is unavailable for this account.','Wrong recipient cannot accept forwarded link');
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.accept_invite((select value::jsonb->>'token' from invite_state where key='invite'),' {"memories":true}',true,'2026-10-24.v2')$$,'PT400','Choose an option for each purpose.','Incomplete family consent rejects acceptance');
select is((select count(*) from public.child_members),0::bigint,'Failed acceptance leaves no membership');
select lives_ok($$select public.accept_invite((select value::jsonb->>'token' from invite_state where key='invite'),' {"memories":true,"milestones":false,"health":false,"personalisation":false,"notifications":false}',true,'2026-10-24.v2')$$,'Recipient accepts once with their own choices');
select is((select role::text from public.child_members where user_id=auth.uid()),'family_viewer','Invited role is server-controlled');
select is((select count(*) from public.consents),5::bigint,'Invitee has five own consent records');
select throws_ok($$select public.accept_invite((select value::jsonb->>'token' from invite_state where key='invite'),' {"memories":true,"milestones":false,"health":false,"personalisation":false,"notifications":false}',true,'2026-10-24.v2')$$,'PT403','This invitation is unavailable for this account.','Consumed token cannot be replayed');
select throws_ok($$select public.create_invite((select value::uuid from invite_state where key='child'),'invite3@example.test','co_parent','Parent')$$,'PT403','You do not have access to invite family.','Viewer cannot invite another user');
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.create_invite((select value::uuid from invite_state where key='child'),'invite3@example.test','owner','Parent')$$,'PT403','Only the owner can invite a co-parent.','Owner role cannot be invited');
insert into invite_state select 'revoked',public.create_invite((select value::uuid from invite_state where key='child'),'invite3@example.test','family_contributor','Aunt')::text;
select public.revoke_invite((select (value::jsonb->>'id')::uuid from invite_state where key='revoked'));
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000003',true);
select throws_ok($$select public.accept_invite((select value::jsonb->>'token' from invite_state where key='revoked'),' {"memories":true,"milestones":false,"health":false,"personalisation":false,"notifications":false}',true,'2026-10-24.v2')$$,'PT403','This invitation is unavailable for this account.','Revoked link fails');
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
insert into invite_state select 'expired',public.create_invite((select value::uuid from invite_state where key='child'),'invite4@example.test','family_viewer','Family')::text;
reset role;
update public.child_invites set expires_at=now()-interval '1 second' where id=(select (value::jsonb->>'id')::uuid from invite_state where key='expired');
set local role authenticated;
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000004',true);
select throws_ok($$select public.accept_invite((select value::jsonb->>'token' from invite_state where key='expired'),' {"memories":true,"milestones":false,"health":false,"personalisation":false,"notifications":false}',true,'2026-10-24.v2')$$,'PT403','This invitation is unavailable for this account.','Expired link fails');
reset role;
select * from finish();
rollback;
